export type RunOutcome = { ok: true; result: RunResult } | { ok: false; errors: (QueryError | DataError | CapError)[] };

export const REASON_WORDS: Record<Reason, string> = {
  outside_data: 'needs bars from before the file starts or after it ends',
  no_bars: 'a window it reads has no bars',
  no_open_bar: 'the first minute of a window has no bar, so there is no open',
  no_regular_hours: 'the session closed early, before regular hours',
  closed_early: 'the session closed before the window it reads',
  no_prior_session: 'there is no earlier session in the calendar',
  event_not_covered: 'the event calendar has no data for that date',
  divide_by_zero: 'a division by zero',
  tie_excluded: 'both events came first in the same minute, left out by the tie rule',
};

function optionError(code: string, message: string, tok = ''): QueryError {
  return { code, part: 'document', offset: 0, length: Math.max(1, tok.length), line: 1, column: 1, message };
}

interface Rec {
  idx: number;
  day: number;
  status: 'present' | 'missing' | 'thin';
  setup: boolean | Undef | null;
  outcome: 'hit' | 'miss' | Undef | null;
  minutes: number | null;
  tie: boolean;
  clipped: boolean;
  windowLength: number;
}

const isDef = (o: Rec['outcome']): o is 'hit' | 'miss' => o === 'hit' || o === 'miss';

export function runSetupOdds(input: RunInput): RunOutcome {
  const limits: Limits = { ...DEFAULT_LIMITS, ...(input.limits ?? {}) };
  const cal = input.calendar ?? defaultCalendar();

  // ---- the query
  let qi: QueryInput;
  let presetId: string | null = null;
  const iq = input.query as Partial<QueryInput> & { preset?: unknown; params?: Record<string, number> };
  if (typeof iq.setup === 'string' || typeof iq.outcome === 'string') {
    // texts, optionally with the preset whose parameters they use (a query document naming a preset)
    qi = input.query as QueryInput;
    if (typeof iq.preset === 'string') presetId = iq.preset;
  } else if (typeof iq.preset === 'string') {
    presetId = iq.preset;
    const p = getPreset(iq.preset);
    if (!p) {
      const r = parseQuery({ setup: 'all', outcome: 'touches 0' }, { preset: iq.preset });
      return { ok: false, errors: r.ok ? [] : r.errors };
    }
    qi = { setup: p.setup, outcome: p.outcome, params: iq.params };
  } else qi = input.query as QueryInput;
  const caps: CapError[] = [];
  for (const part of ['setup', 'outcome'] as const) {
    const n = (qi[part] ?? '').length;
    if (n > limits.maxQueryChars) caps.push({ code: 'C_QUERY_TOO_LONG', limit: limits.maxQueryChars, message: `The ${part} is ${n} characters; the limit is ${limits.maxQueryChars}.` });
  }
  if (caps.length) return { ok: false, errors: caps };

  // ---- options
  const optErrors: QueryError[] = [];
  const minCoverage = input.minCoverage ?? 0.8;
  if (typeof minCoverage !== 'number' || !(minCoverage >= 0 && minCoverage <= 1))
    optErrors.push(optionError('E_BAD_OPTION', `minCoverage must be a number from 0 to 1; got ${String(minCoverage)}.`));
  const tie = input.tie ?? 'miss';
  if (tie !== 'miss' && tie !== 'hit' && tie !== 'exclude') optErrors.push(optionError('E_BAD_OPTION', `tie must be miss, hit or exclude; got ${String(tie)}.`));
  if (input.tickSize !== undefined && !(typeof input.tickSize === 'number' && Number.isFinite(input.tickSize) && input.tickSize > 0))
    optErrors.push(optionError('E_BAD_OPTION', `tickSize must be a positive number; got ${String(input.tickSize)}.`));
  let from: number | null = null;
  let to: number | null = null;
  for (const [key, v] of [['from', input.from], ['to', input.to]] as const) {
    if (v === undefined || v === null) continue;
    const d = parseDate(v);
    if (d === null) optErrors.push(optionError('E_BAD_DATE', `'${v}' is not a date. Write YYYY-MM-DD.`, v));
    else if (key === 'from') from = d;
    else to = d;
  }
  if (optErrors.length) return { ok: false, errors: optErrors };

  const parsed = parseQuery(qi, { tickSize: input.tickSize, preset: presetId ?? undefined, maxChars: limits.maxQueryChars });
  if (!parsed.ok) return { ok: false, errors: parsed.errors };
  const pq = parsed.query;
  const q = pq.internal;

  // ---- the bars
  const bars = input.bars;
  if (bars.length > limits.maxBars)
    return { ok: false, errors: [{ code: 'C_MAX_BARS', limit: limits.maxBars, message: `The data has ${bars.length} bars; this surface reads at most ${limits.maxBars}.` }] };
  const dataErrors = checkBars(bars, cal);
  if (dataErrors.length) return { ok: false, errors: dataErrors };
  if (q.readsVolume && !bars.volume)
    return { ok: false, errors: [{ code: 'D_NO_VOLUME', line: null, column: null, message: 'The query reads volume, but these bars have no volume column.' }] };
  const s = assignSessions(bars, cal);
  if (s.assigned === 0)
    return { ok: false, errors: [{ code: 'D_NO_SESSIONS', line: null, column: null, message: 'None of these bars falls inside a trading session the calendar knows.' }] };
  const range = analysisRange(s, from, to);
  if (range.length > limits.maxSessions)
    return {
      ok: false,
      errors: [{ code: 'C_MAX_SESSIONS', limit: limits.maxSessions, message: `The range holds ${range.length} sessions; this surface reads at most ${limits.maxSessions}. Narrow it with from and to.` }],
    };

  // ---- evaluation
  const ev = new Evaluator(s, q, tie);
  const recs: Rec[] = [];
  const total = range.length;
  for (let r = 0; r < total; r++) {
    if (r > 0 && r % 50 === 0) {
      input.onProgress?.(r, total);
      if (input.shouldAbort?.()) return { ok: false, errors: [{ code: 'C_ABORTED', limit: null, message: 'The run was cancelled.' }] };
    }
    const idx = range[r];
    const rec: Rec = { idx, day: cal.days[idx], status: 'present', setup: null, outcome: null, minutes: null, tie: false, clipped: false, windowLength: 0 };
    if (s.dayFirst[idx] < 0) rec.status = 'missing';
    else if (hasRth(cal, idx)) {
      const rthMinutes = rthClose(cal, idx) - 930;
      const [lo, hi] = dayRange(s, idx, 930, rthClose(cal, idx));
      if ((hi - lo) / rthMinutes < minCoverage) rec.status = 'thin';
    }
    if (rec.status === 'present') {
      rec.setup = ev.setup(idx);
      const o = ev.outcome(idx);
      rec.outcome = o.value;
      rec.minutes = o.minutes;
      rec.tie = o.tie;
      rec.clipped = o.clipped;
      rec.windowLength = o.windowLength;
    }
    recs.push(rec);
  }
  input.onProgress?.(total, total);
  if (input.shouldAbort?.()) return { ok: false, errors: [{ code: 'C_ABORTED', limit: null, message: 'The run was cancelled.' }] };

  return { ok: true, result: buildResult(pq, cal, s, recs, { tie, minCoverage, from: input.from ?? null, to: input.to ?? null, preset: presetId, includeSessions: !!input.includeSessions, maxSessionRows: limits.maxSessionRows, parseWarnings: parsed.warnings }) };
}

interface BuildOpts {
  tie: 'miss' | 'hit' | 'exclude';
  minCoverage: number;
  from: string | null;
  to: string | null;
  preset: string | null;
  includeSessions: boolean;
  maxSessionRows: number;
  parseWarnings: { code: string; message: string }[];
}

function half(rs: Rec[]): HalfStats {
  const k = rs.filter((r) => r.outcome === 'hit').length;
  const g = groupStats(k, rs.length);
  return { ...g, firstDay: rs.length ? formatDate(rs[0].day) : null, lastDay: rs.length ? formatDate(rs[rs.length - 1].day) : null };
}

function buildResult(pq: ParsedQuery, cal: Calendar, s: ReturnType<typeof assignSessions>, recs: Rec[], o: BuildOpts): RunResult {
  const q = pq.internal;
  const present = recs.filter((r) => r.status === 'present');
  const setupGroup = present.filter((r) => r.setup === true && isDef(r.outcome));
  const complement = present.filter((r) => r.setup === false && isDef(r.outcome));
  const baseline = present.filter((r) => isDef(r.outcome));
  const unmeasured = present.filter((r) => !(r.setup === true || r.setup === false) || !isDef(r.outcome));
  const hits = (rs: Rec[]): number => rs.filter((r) => r.outcome === 'hit').length;
  const setupStats = groupStats(hits(setupGroup), setupGroup.length);
  const baseStats = groupStats(hits(baseline), baseline.length);
  const compStats = groupStats(hits(complement), complement.length);

  const reasons: Record<string, number> = {};
  const reasonCounts = new Map<Reason, number>();
  for (const r of unmeasured) {
    const reason = r.setup instanceof Undef ? r.setup.reason : (r.outcome as Undef).reason;
    reasonCounts.set(reason, (reasonCounts.get(reason) ?? 0) + 1);
  }
  for (const k of REASONS) if (reasonCounts.get(k)) reasons[k] = reasonCounts.get(k)!;

  // lift
  const rate = setupStats.rate;
  const b = baseStats.rate;
  const lift = {
    points: rate === null || b === null ? null : rate - b,
    ratio: rate === null || b === null || b === 0 ? null : rate / b,
    baselineInsideInterval: setupStats.lo === null || setupStats.hi === null || b === null ? null : setupStats.lo <= b && b <= setupStats.hi,
  };

  // halves
  const n = setupGroup.length;
  const h1 = Math.floor(n / 2);
  const first = half(setupGroup.slice(0, h1));
  const second = half(setupGroup.slice(h1));
  const withheld = first.n < HALF_MIN || second.n < HALF_MIN;

  // years
  const byYear: YearRow[] = [];
  if (recs.length) {
    const y0 = yearOf(recs[0].day);
    const y1 = yearOf(recs[recs.length - 1].day);
    for (let y = y0; y <= y1; y++) {
      const sg = setupGroup.filter((r) => yearOf(r.day) === y);
      const bg = baseline.filter((r) => yearOf(r.day) === y);
      byYear.push({ year: y, setup: groupStats(hits(sg), sg.length), baseline: groupStats(hits(bg), bg.length), few: sg.length < 10 });
    }
  }

  // time to event
  const out = q.outcome;
  const isTimed = out.form === 'event' && !out.neg;
  let tte: TimeToEvent | null = null;
  if (isTimed) {
    const mins = setupGroup.filter((r) => r.outcome === 'hit').map((r) => r.minutes as number);
    const longest = setupGroup.reduce((m, r) => Math.max(m, r.windowLength), 0);
    tte = timeToEvent(pq.window.kind === 'event' ? pq.window.start : '', mins, n, longest);
  }

  const ties = present.filter((r) => r.tie).length;
  const clipped = present.filter((r) => r.clipped && isDef(r.outcome)).length;
  const missing = recs.filter((r) => r.status === 'missing').length;
  const thin = recs.filter((r) => r.status === 'thin').length;
  const ign = s.ignored;
  const ignoredTotal = ign.offCalendar + ign.halt + ign.afterClose + ign.outOfCoverage;

  // ---- warnings, in the fixed order of SPEC § 9.8
  const W: { code: string; message: string }[] = [];
  const add = (code: string, message: string): void => {
    W.push({ code, message });
  };
  const isAll = q.setup.t === 'all';
  if (n === 0) add('W_NONE', 'No session met the setup, so there is nothing to measure.');
  if (n >= 1 && n < 10)
    add('W_ANECDOTAL', `Only ${n} ${plural(n, 'session', 'sessions')} met the setup. That is too few to say anything: the true rate could be anywhere from ${pct(setupStats.lo!)} to ${pct(setupStats.hi!)}.`);
  if (n >= 10 && n < 30) add('W_THIN', `${n} sessions is a thin sample. Read the interval, not the rate.`);
  if (n >= 10 && setupStats.hi! - setupStats.lo! > WIDE_INTERVAL) add('W_WIDE_INTERVAL', `The 95% interval is ${fmt(100 * (setupStats.hi! - setupStats.lo!), 1)} percentage points wide.`);
  if (!isAll && n >= 10 && lift.baselineInsideInterval)
    add('W_NOT_DISTINGUISHABLE', `The baseline rate (${pct(b!)}) lies inside the setup's interval, so this sample cannot tell the setup apart from an ordinary session.`);
  const nb = baseline.length;
  if (nb === 0) add('W_BASELINE_NONE', 'No session could be measured, so there is no baseline.');
  if (nb >= 1 && nb < 30) add('W_BASELINE_SMALL', `The baseline has only ${nb} ${plural(nb, 'session', 'sessions')}.`);
  if (n >= 2 && withheld) add('W_HALVES_THIN', 'Each half needs at least 10 sessions to be compared, so the halves are shown as counts only.');
  if (!withheld && (first.hi! < second.lo! || second.hi! < first.lo!))
    add('W_HALVES_DISAGREE', `The two halves disagree: ${pct(first.rate!)} in the first against ${pct(second.rate!)} in the second. The setup may not be stable over time.`);
  const hitCount = tte ? tte.count : 0;
  if (isTimed && hitCount >= 1 && hitCount < TIMING_MIN)
    add('W_TIMING_THIN', `Only ${hitCount} ${plural(hitCount, 'hit', 'hits')} to time, so the timing is shown as a list, not a distribution.`);
  if (ties > 0) {
    const words = o.tie === 'miss' ? 'counted them as misses' : o.tie === 'hit' ? 'counted them as hits' : 'left them out';
    add('W_TIES', `Sessions whose two events came first in the same minute: ${ties}. The tie rule ${words}.`);
  }
  if (clipped > 0) add('W_CLIPPED', `Sessions judged on a window shortened by an early close: ${clipped}.`);
  if (unmeasured.length > 0) {
    const list = REASONS.filter((r) => reasonCounts.get(r)).map((r) => `${reasonCounts.get(r)} ${REASON_WORDS[r]}`).join('; ');
    add('W_UNMEASURED', `Sessions that could not be measured: ${unmeasured.length} (${list}).`);
  }
  if (missing > 0) add('W_MISSING', `Trading days in the range with no bars at all: ${missing}.`);
  if (thin > 0) add('W_THIN_SESSIONS', `Sessions left out because their bars cover less than ${String(100 * o.minCoverage)}% of the regular-hours minutes: ${thin}.`);
  if (ignoredTotal > 0) {
    const parts: string[] = [];
    if (ign.offCalendar) parts.push(`${ign.offCalendar} on closed days`);
    if (ign.halt) parts.push(`${ign.halt} in the 17:00 to 18:00 halt`);
    if (ign.afterClose) parts.push(`${ign.afterClose} after an early close`);
    if (ign.outOfCoverage) parts.push(`${ign.outOfCoverage} outside the calendar's years`);
    add('W_IGNORED_BARS', `Bars outside every session, ignored: ${ignoredTotal} (${parts.join(', ')}).`);
  }
  if (recs.length) {
    const lo = recs[0].idx;
    const hi = recs[recs.length - 1].idx;
    const mapped = cal.mappedEvents.filter((m) => q.eventKinds.includes(m.kind) && m.idx >= lo && m.idx <= hi);
    if (mapped.length)
      add('W_EVENT_MAPPED', `Some event dates fell on a closed day and count on the next trading day: ${mapped.map((m) => `${EVENT_LABEL[m.kind]} ${m.dateEt} on ${m.tradingDay}`).join(', ')}.`);
  }
  if (q.eventKinds.includes('opex') || q.eventKinds.includes('roll'))
    add('W_CONVENTION_EVENTS', 'OPEX and roll dates follow a convention, not a published calendar, so a few may be off by a day.');
  const g = sparseGap(s, present);
  if (g !== null && g >= 2)
    add('W_SPARSE_BARS', `These bars look like ${g}-minute bars. Setup Odds reads every bar as one minute, so it cannot see inside a longer bar.`);
  if (s.bars.unsorted) add(W_UNSORTED.code, W_UNSORTED.message);
  for (const w of o.parseWarnings) if (w.code === 'W_EMPTY_BETWEEN') add(w.code, w.message);

  const result: RunResult = {
    schema: 'algolift.setup-odds.result/1',
    engineVersion: ENGINE_VERSION,
    calendarVersion: cal.version,
    query: {
      setup: pq.setup,
      outcome: pq.outcome,
      params: q.params,
      preset: o.preset,
      decisionTime: pq.decisionTime,
      window: pq.window,
      tie: o.tie,
      minCoverage: o.minCoverage,
      from: o.from,
      to: o.to,
    },
    data: {
      label: s.bars.label,
      bars: s.assigned,
      firstBar: isoWithOffset(cal.ny, s.firstAssigned),
      lastBar: isoWithOffset(cal.ny, s.lastAssigned),
      ignored: { offCalendar: ign.offCalendar, halt: ign.halt, afterClose: ign.afterClose, outOfCoverage: ign.outOfCoverage },
      hasVolume: s.bars.volume !== null,
    },
    sessions: {
      inRange: recs.length,
      firstDay: recs.length ? formatDate(recs[0].day) : null,
      lastDay: recs.length ? formatDate(recs[recs.length - 1].day) : null,
      missing,
      thin,
      present: present.length,
      setupTrue: present.filter((r) => r.setup === true).length,
      setupFalse: present.filter((r) => r.setup === false).length,
      setupUndefined: present.filter((r) => r.setup instanceof Undef).length,
      measured: nb,
      unmeasured: unmeasured.length,
      unmeasuredReasons: reasons,
      ties,
      clipped,
    },
    setup: setupStats,
    baseline: baseStats,
    complement: compStats,
    lift,
    stability: { first, second, withheld },
    byYear,
    timeToEvent: tte,
    tier: setupStats.tier,
    warnings: W,
    display: null as unknown as Display,
  };
  const hitMins = setupGroup.filter((r) => r.outcome === 'hit').map((r) => r.minutes as number).sort((a, b) => a - b);
  result.display = buildDisplay(result, isAll, isTimed, hitMins);
  if (o.includeSessions && o.maxSessionRows > 0) {
    const rows: SessionRow[] = recs.map((r) => ({
      day: formatDate(r.day),
      status: r.status,
      setup: r.setup === true || r.setup === false ? r.setup : null,
      setupReason: r.setup instanceof Undef ? r.setup.reason : null,
      outcome: isDef(r.outcome) ? r.outcome : null,
      outcomeReason: r.outcome instanceof Undef ? r.outcome.reason : null,
      minutes: r.minutes,
      tie: r.tie,
      clipped: r.clipped,
    }));
    result.sessionRows = Number.isFinite(o.maxSessionRows) ? rows.slice(0, o.maxSessionRows) : rows;
  }
  return result;
}

/** The lower median of minute gaps between consecutive bars inside one RTH, over present sessions (at least 100 gaps). */
function sparseGap(s: ReturnType<typeof assignSessions>, present: Rec[]): number | null {
  const gaps: number[] = [];
  for (const r of present) {
    if (!hasRth(s.cal, r.idx)) continue;
    const [lo, hi] = dayRange(s, r.idx, 930, rthClose(s.cal, r.idx));
    for (let p = lo + 1; p < hi; p++) gaps.push(s.aMin[p] - s.aMin[p - 1]);
  }
  if (gaps.length < 100) return null;
  gaps.sort((a, b) => a - b);
  return gaps[Math.floor((gaps.length - 1) / 2)];
}

function groupLine(g: GroupStats, noneText: string): string {
  if (g.tier === 'none') return noneText;
  if (g.tier === 'anecdotal')
    return `${g.k} of ${g.n} ${plural(g.n, 'session', 'sessions')} saw the outcome. Too few sessions for a rate (95% interval ${pct(g.lo!)} to ${pct(g.hi!)}).`;
  return `${g.k} of ${g.n} sessions saw the outcome: ${pct(g.rate!)} (95% interval ${pct(g.lo!)} to ${pct(g.hi!)}).`;
}

function buildDisplay(r: RunResult, isAll: boolean, isTimed: boolean, hitMins: number[]): Display {
  const setup = groupLine(r.setup, 'No session met the setup.');
  const baseline = groupLine(r.baseline, 'No session could be measured.');
  let lift: string | null = null;
  const lowTier = (t: Tier): boolean => t === 'none' || t === 'anecdotal';
  if (!isAll && !lowTier(r.setup.tier) && !lowTier(r.baseline.tier) && r.lift.points !== null)
    lift = r.lift.ratio === null ? `${pointsText(r.lift.points)} percentage points.` : `${pointsText(r.lift.points)} percentage points (${ratioText(r.lift.ratio)} times the baseline).`;
  let halves: [string, string] | null = null;
  if (r.setup.n >= 2) {
    const line = (name: string, h: HalfStats): string => {
      if (h.n === 0) return `${name} 0: none`;
      const base = `${name} ${h.n} (${h.firstDay} to ${h.lastDay}): ${h.k} of ${h.n}`;
      return r.stability.withheld ? base : `${base}, ${pct(h.rate!)} (${pct(h.lo!)} to ${pct(h.hi!)})`;
    };
    halves = [line('first', r.stability.first), line('second', r.stability.second)];
  }
  const years = r.byYear.map((y) =>
    y.setup.n >= 10 ? `${y.year}  ${y.setup.k} of ${y.setup.n}  ${pct(y.setup.rate!)}` : y.setup.n >= 1 ? `${y.year}  ${y.setup.k} of ${y.setup.n}  (too few)` : `${y.year}  none`,
  );
  let timing: string | null = null;
  let histogram: string[] | null = null;
  const t = r.timeToEvent;
  if (isTimed && t) {
    if (t.count === 0) timing = 'No hits to time.';
    else if (t.count < TIMING_MIN) {
      timing = `${t.count} ${plural(t.count, 'hit', 'hits')}, minutes after ${t.start}: ${hitMins.join(', ')}`;
    } else {
      timing = `${t.count} hits, minutes after ${t.start}: median ${minutesText(t.p50!)}, middle half ${minutesText(t.p25!)} to ${minutesText(t.p75!)}, 10% by ${minutesText(t.p10!)}, 90% by ${minutesText(t.p90!)}`;
      const maxCount = Math.max(...t.bins.map((b) => b.count));
      histogram = t.bins.map((b) => {
        const label = `(${b.lo},${b.hi}]`.padEnd(11, ' ');
        const bar = b.count === 0 ? 0 : Math.max(1, Math.floor((b.count / maxCount) * 30 + 0.5));
        return label + '#'.repeat(bar) + ' ' + b.count;
      });
    }
  }
  return { setup, baseline, lift, halves, years, timing, histogram, warnings: r.warnings.map((w) => w.message) };
}
